import{_ as s,o as a,c as t,a5 as i}from"./chunks/framework.DukzBDYY.js";const c=JSON.parse('{"title":"Holds and Payment","description":"","frontmatter":{},"headers":[],"relativePath":"guides/holds.md","filePath":"guides/holds.md"}'),n={name:"guides/holds.md"};function l(o,e,h,r,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="holds-and-payment" tabindex="-1">Holds and Payment <a class="header-anchor" href="#holds-and-payment" aria-label="Permalink to &quot;Holds and Payment&quot;">​</a></h1><p>When a customer chooses a slot, it’s <strong>held</strong> for their cart. When they pay, it’s <strong>booked</strong>.</p><h2 id="holds" tabindex="-1">Holds <a class="header-anchor" href="#holds" aria-label="Permalink to &quot;Holds&quot;">​</a></h2><p>A held slot counts towards the slot’s limit, so two customers checking out at once can’t both take the last place. The hold lasts 15 minutes, or <code>holdMinutes</code> in the <a href="/getting-started/configuration">config file</a>.</p><p>If the customer takes longer, the hold runs out, and someone else can take the place. When they come back and pay:</p><ul><li>If the slot still has room, it’s held again and the payment goes ahead.</li><li>If it filled up, payment stops with <em>That delivery time is no longer available</em>, and the customer chooses another.</li></ul><p>Choosing again, or saving the cart with the same slot, renews the hold.</p><p>Only carts with something in them can hold a slot, so slots can’t be filled by visitors who aren’t shopping. To turn holds off, set <code>holdMinutes</code> to <code>0</code>: then only paid orders take places, and the last place goes to whoever pays first.</p><h2 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h2><p>When an order’s shipping method has slots, Commerce’s payment form (<code>commerce/payments/pay</code>) checks the slot first. Payment doesn’t go ahead, and the order shows an error on <code>deliverySlot</code>, when:</p><ul><li>the order has no slot: <em>Choose a delivery time.</em></li><li>the slot is full or has closed: <em>That delivery time is no longer available. Choose another.</em></li></ul><p>Show the error on your payment page:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cart.getFirstError(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deliverySlot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {{ cart.getFirstError(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deliverySlot&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{ url(&#39;checkout/shipping&#39;) }}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Choose a time&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><h2 id="booking" tabindex="-1">Booking <a class="header-anchor" href="#booking" aria-label="Permalink to &quot;Booking&quot;">​</a></h2><p>When the order is completed, its slot is booked. Booked slots never expire, show on the <a href="/guides/run-sheet">run sheet</a>, and appear on the order in the control panel.</p><p>Payments taken in the control panel aren’t checked for a slot, so staff can take phone orders without one.</p><h2 id="cancelled-and-deleted-orders" tabindex="-1">Cancelled and deleted orders <a class="header-anchor" href="#cancelled-and-deleted-orders" aria-label="Permalink to &quot;Cancelled and deleted orders&quot;">​</a></h2><p>When an order is deleted, its slot is freed, and it leaves the run sheet. A cancelled order keeps its slot, so it still shows on the run sheet and takes a place; delete it to free the place.</p>`,18)])])}const E=s(n,[["render",l]]);export{c as __pageData,E as default};
